}

function checkJumps() {
  const p = G.player;
  if (!p || p.onFoot || !p.vehicle) return;
  for (const j of G.jumps) {
    if (j.done) continue;
    if (groundDist(p.pos.x, p.pos.z, j.x, j.z) < 5 && Math.abs(p.vehicle.speed || 0) > 14) {
      j.done = true;
      p.vehicle.jumpT = 1.2;
      G.stats.jumps++;
      addCash(500);
      addRp(10);
      moveStanding(j.district, 5);
      toast('STUNT JUMP! +$500 (' + G.stats.jumps + '/5)', 3);
    }
