}

/** The Neon Mile Sprint: a checkpoint race around the east side. */
export const RACE = {
  start: { x: 224, z: 0 },
  checkpoints: [{ x: 224, z: 112 }, { x: 280, z: 112 }, { x: 280, z: -112 }, { x: 224, z: -112 }],
  finish: { x: 224, z: 0 },
};

export function startRace() {
  const p = G.player;
  if (!p || p.onFoot) {
    toast('Get in a car first — the race starts at Neon Mile', 3);
    return false;
